using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Collections.Generic;
using System.Linq;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine("=== BUILD RESULT ===");
Console.WriteLine($"Succeeded: {build.Succeeded}");
Console.WriteLine();

// Collect all errors
var errors = new List<(string Project, string Code, string File, int Line, string Message)>();
build.VisitAllChildren<Error>(e => {
    var project = "";
    var node = e.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    errors.Add((project, e.Code ?? "", e.File ?? "", e.LineNumber, e.Text ?? ""));
});

Console.WriteLine($"=== ERRORS ({errors.Count}) ===");
foreach (var (proj, code, file, line, msg) in errors) {
    Console.WriteLine($"[{code}] {proj}");
    Console.WriteLine($"  File: {file}:{line}");
    Console.WriteLine($"  {msg}");
    Console.WriteLine();
}

// Collect warnings
var warnings = new List<(string Project, string Code, string Message)>();
build.VisitAllChildren<Warning>(w => {
    var project = "";
    var node = w.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    warnings.Add((project, w.Code ?? "", w.Text ?? ""));
});

Console.WriteLine($"=== WARNINGS ({warnings.Count}) ===");
foreach (var (proj, code, msg) in warnings.Take(20)) {
    Console.WriteLine($"[{code}] {proj}: {msg}");
}
if (warnings.Count > 20) Console.WriteLine($"  ... and {warnings.Count - 20} more warnings");

// Show project dependency tree and which projects failed
Console.WriteLine();
Console.WriteLine("=== PROJECT BUILD STATUS ===");
build.VisitAllChildren<Project>(p => {
    if (p.Name.EndsWith(".csproj") || p.Name.EndsWith(".fsproj") || p.Name.EndsWith(".vbproj")) {
        var hasErrors = false;
        p.VisitAllChildren<Error>(e => hasErrors = true);
        if (hasErrors)
            Console.WriteLine($"  FAILED: {p.Name} (Target: {p.TargetFramework})");
    }
});
EOF
