    if (n.Name == "PackageReference" || n.Name == "Reference") {
        var project = "";
        var node = n.Parent;
        while (node != null) {
            if (node is Project p) { project = p.Name; break; }
            node = node.Parent;
        }
        Console.WriteLine($"  {project}: {n.Name} = {n}");
    }
});

