    if (ai.Name == "PackageReference") {
        var project = "";
        var node = ai.Parent;
        while (node != null) {
            if (node is Project p) { project = p.Name; break; }
            node = node.Parent;
        }
        foreach (var child in ai.Children) {
            Console.WriteLine($"  {project}: {child}");
        }
    }
});
